 * 	PORT: {
 * 		schema: (value) => {
 * 			if (value === undefined) return 3000;
 * 			const port = Number(value);
 * 			if (!Number.isInteger(port)) throw new Error('PORT must be an integer');
 * 			return port;
 * 		}
 * 	}
